before.content:
String rollback = runner.commands.stream().flatMap(List::stream)
        .filter(value -> value.contains(".rollback"))
        .findFirst().orElseThrow();
assertTrue(rollback.contains("systemctl --user stop ji-host.service"));
assertTrue(rollback.contains("backups-before"));
assertTrue(rollback.contains(".pre-v"));
assertTrue(rollback.contains(".restore"));

after.content:
String rollback = runner.commands.stream().flatMap(List::stream)
        .filter(value -> value.contains(".rollback"))
        .findFirst().orElseThrow();
assertTrue(rollback.contains("if test -f \"$activated\"; then"));
assertTrue(rollback.contains("systemctl --user stop ji-host.service"));
assertTrue(rollback.indexOf("if test -f \"$activated\"; then")
        < rollback.indexOf("systemctl --user stop ji-host.service"));
assertTrue(rollback.contains("backups-before"));
assertTrue(rollback.contains(".pre-v"));
assertTrue(rollback.contains(".restore"));
